# Define hyperparameters based on iteration number (e.g., iter=1)
iteration = 2  # Example for Iteration 2
batch_size_options = [8, 16, 32]
lr_options = [0.001, 0.0001, 0.00001]
conv_layers_options = [2, 3, 4]
dropout_options = [0.0, 0.2, 0.5]
batch_size = batch_size_options[iteration % 3]
lr = lr_options[iteration % 3]
num_conv_layers = conv_layers_options[iteration % 3]
dropout_rate = dropout_options[(iteration // 3) % len(dropout_options)]

# Define number of output classes
NUM_SPECIES = 206

# Data loading
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")
train_loader = get_dataloader(DATA_DIR, METADATA_FILE, batch_size=batch_size)

# Limit training dataset to 15000 samples for faster iteration
subset_indices = list(range(min(15000, len(train_loader.dataset))))
train_subset = torch.utils.data.Subset(train_loader.dataset, subset_indices)
train_loader.dataset = train_subset

# Model definition
class BirdCLEFModel(nn.Module):
    def __init__(self, num_species=NUM_SPECIES, dropout_rate=dropout_rate):
        super(BirdCLEFModel, self).__init__()
        channels = [16, 32, 64, 128][:num_conv_layers]
        
        self.conv_layers = nn.Sequential()
        for i in range(num_conv_layers):
            conv = nn.Conv2d(channels[i-1] if i > 0 else 1, channels[i], kernel_size=3, padding=1)
            bn = nn.BatchNorm2d(channels[i])
            relu = nn.ReLU()
            self.conv_layers.add_module(f'conv{i+1}', conv)
            self.conv_layers.add_module(f'bn{i+1}', bn)
            self.conv_layers.add_module(f'relu{i+1}', relu)
        
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(
            nn.Linear(channels[-1], 128),
            nn.ReLU(),
            nn.Dropout(dropout_rate),
            nn.Linear(128, num_species)
        )
    
    def forward(self, x):
        x = self.conv_layers(x)
        x = self.pool(x).view(x.size(0), -1)
        return torch.sigmoid(self.classifier(x))

# Instantiate model
model = BirdCLEFModel()
if torch.cuda.is_available():
    model.to('cuda')

# Loss function and optimizer
criterion = nn.BCELoss()
optimizer = optim.Adam(model.parameters(), lr=lr, weight_decay=0.001)

# Training loop
epochs = 6
