for epoch in range(epochs):
    for inputs, labels in tqdm(train_loader, desc=f'Epoch {epoch+1}'):
        if torch.cuda.is_available():
            inputs, labels = inputs.to('cuda'), labels.to('cuda')
        
        optimizer.zero_grad()
        outputs = model(inputs)
        loss = criterion(outputs, labels.float())
        loss.backward()
        optimizer.step()
        
        total_train_loss += loss.item()
        torch.cuda.empty_cache()  # Prevent GPU fragmentation

# Evaluate on validation set
model.eval()
val_subset_indices = list(range(min(5000, len(train_loader.dataset))))
val_subset = torch.utils.data.Subset(train_loader.dataset, val_subset_indices)
val_loader = torch.utils.data.DataLoader(val_subset, batch_size=32, shuffle=False)

all_preds = []
